entries[47046] = { ["name"] = "Alchimistenstein des Wächters", ["text"] = "Wirken in 50 sek.\nReagenzien:\nAlchimistenstein , Urluft (6), Nethervortex (2)\nAlchimistenstein des Wächters\nWird beim Aufheben gebunden\nEinzigartigSchmuck\nBenötigt Alchimie\n(350)\nAnlegen: Erhöht die Verteidigungswertung um 54.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar." }
