entries[351766] = { ["name"] = "Große Trommeln des Krieges", ["text"] = "Wirken in 50 sek.\nReagenzien:\nSchweres Knotenhautleder (3), Teufelsschuppen (3)\nGroße Trommeln des Krieges\nBenötigt Lederverarbeitung\n(340)\nBenutzen: Erhöht bei allen Gruppenmitgliedern innerhalb von 40 Metern die Angriffskraft um 60 und den Zauberschaden um 30. Hält 30 Sek. lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen" }
entries[351768] = { ["name"] = "Große Trommeln des Tempos", ["text"] = "Wirken in 50 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Windschuppe (4)\nGroße Trommeln des Tempos\nBenötigt Lederverarbeitung\n(340)\nBenutzen: Erhöht das Bewegungstempo von Gruppenmitgliedern innerhalb von 40 Metern um 15%. Hält 30 Sek. lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen" }
entries[351769] = { ["name"] = "Große Trommeln der Wiederherstellung", ["text"] = "Wirken in 50 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Netherdrachenschuppe (4)\nGroße Trommeln der Wiederherstellung\nBenötigt Lederverarbeitung\n(350)\nBenutzen: Stellt im Verlauf von 15 Sek. 600 Gesundheit und Mana bei Gruppenmitgliedern innerhalb von 40 Metern wieder her. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen" }
entries[351770] = { ["name"] = "Große Trommeln der Panik", ["text"] = "Wirken in 50 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Teufelsbalg (4)\nGroße Trommeln der Panik\nBenötigt Lederverarbeitung\n(350)\nBenutzen: Unheimliche Klänge, lassen 5 Feinde in einem Umkreis von 8 Metern 2 Sek. lang voller Schrecken flüchten. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen" }
entries[351771] = { ["name"] = "Große Trommeln der Schlacht", ["text"] = "Wirken in 50 sek.\nReagenzien:\nSchweres Knotenhautleder (6), Dickes Grollhufleder (4)\nGroße Trommeln der Schlacht\nBenötigt Lederverarbeitung\n(350)\nBenutzen: Erhöht Nahkampf-, Distanz- und Zaubertempowertung von Gruppenmitgliedern innerhalb von 40 Metern um 80. Hält 30 Sek. lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen" }
